function validate([nums1, nums2]) {
  const n = nums1.length;
  if (n < 1 || n > 100000) return 'nums1 needs 1 to 100000 values.';
  if (nums2.length !== n) return 'nums1 and nums2 must have the same length.';
  if (nums1.some(v => v < 1 || v > n) || nums2.some(v => v < 1 || v > n)) return 'Every value is between 1 and n, the arrays\' length.';
  return null;
}

