function minimumTotalCost(nums1, nums2) {
  const n = nums1.length;
  const count = new Array(n + 1).fill(0);
  let cost = 0;
  let involved = 0;
  let dominant = 0;
  let dominantCount = 0;

  for (let i = 0; i < n; i++) {
    if (nums1[i] !== nums2[i]) {
      continue;
    }
    cost += i;
    involved++;
    count[nums1[i]]++;
    if (count[nums1[i]] > dominantCount) {
      dominant = nums1[i];
      dominantCount = count[nums1[i]];
    }
  }

  for (let i = 0; i < n && dominantCount * 2 > involved; i++) {
    if (nums1[i] !== nums2[i] && nums1[i] !== dominant && nums2[i] !== dominant) {
      cost += i;
      involved++;
    }
  }

  if (dominantCount * 2 > involved) {
    return -1;
  }
  return cost;
}

