function minimumTotalCost(nums1, nums2) {
  // Dijkstra over every arrangement of nums1, using a bucket per total cost (all move costs are positive).
  const n = nums1.length;
  const best = new Map([[nums1.join(','), 0]]);
  const buckets = [[nums1.slice()]];
  let pending = 1;
  for (let d = 0; pending > 0; d++) {
    for (const arr of buckets[d] || []) {
      pending--;
      if (best.get(arr.join(',')) < d) continue;
      if (arr.every((v, i) => v !== nums2[i])) return d;
      for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
          if (arr[i] === arr[j]) continue;
          const next = arr.slice();
          next[i] = arr[j];
          next[j] = arr[i];
          const key = next.join(',');
          const nd = d + i + j;
          if (!best.has(key) || best.get(key) > nd) {
            best.set(key, nd);
            (buckets[nd] = buckets[nd] || []).push(next);
            pending++;
          }
        }
      }
    }
  }
  return -1;
}

