function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 6);
  // A few popular values make a dominant value (and sometimes -1) likely.
  const span = 1 + Math.floor(rand() * (size === 'large' ? 6 : n));
  const pick = () => (rand() < 0.15 ? 1 + Math.floor(rand() * n) : 1 + Math.floor(rand() * span));
  const nums1 = Array.from({ length: n }, pick);
  const sameRate = 0.8 * rand();
  const nums2 = nums1.map(v => (rand() < sameRate ? v : pick()));
  return [nums1, nums2];
}
